 function revealCharacters(element,delay=0){if(!element||reduce)return;const value=element.textContent;element.setAttribute('aria-label',value);const frag=document.createDocumentFragment();let n=0;value.split(/(\s+)/).forEach(word=>{if(!word.trim()){frag.append(document.createTextNode(word));return}const group=document.createElement('span');group.className='type-word';group.setAttribute('aria-hidden','true');for(const letter of word){const ch=document.createElement('span');ch.className='type-char';ch.textContent=letter;ch.style.setProperty('--char-delay',(delay+(n++)*9)+'ms');group.append(ch)}frag.append(group)});element.replaceChildren(frag)}
