 const tiles=$$('.floating-image'),showcase=$('.showcase'),featureStack=$('.feature-stack'),features=$$('.feature-stack .feature'),interlude=$('.interlude'),teaser=$('.dashboard-teaser'),closing=$('.closing'),footer=$('.footer-word');let ticking=false;if(featureStack&&!reduce)featureStack.classList.add('is-pinned');
 function update(){ticking=false;if(reduce)return;const height=innerHeight;statements.forEach(({element,words})=>{const rect=element.getBoundingClientRect();if(rect.bottom<-50||rect.top>height+100)return;const p=clamp((height*.88-rect.top)/(height*.40+rect.height*.5));words.forEach((word,i)=>{const q=clamp((p-(i/Math.max(1,words.length))*.58)/.42);word.style.opacity=String(.13+.87*q);word.style.filter='blur('+(4*(1-q)).toFixed(2)+'px)';word.style.transform='translateY('+(5*(1-q)).toFixed(1)+'px)'})});if(showcase){const r=showcase.getBoundingClientRect();if(r.bottom>0&&r.top<height){const p=(height-r.top)/(height+r.height)-.5;tiles.forEach((tile,i)=>{tile.style.setProperty('--tile-y',(p*(i%2?150:-130)).toFixed(1)+'px');tile.style.setProperty('--tile-x',(p*(i%3?32:-40)).toFixed(1)+'px')})}}if(featureStack){const r=featureStack.getBoundingClientRect();if(r.bottom>0&&r.top<height){const phase=clamp(-r.top/Math.max(1,r.height-height))*3,active=phase>=1.85?2:phase>=.85?1:0,alphas=[0,0,0];alphas[active]=1;features.forEach((feature,i)=>{const a=alphas[i];feature.style.opacity=String(a);feature.style.setProperty('--panel-scale',String(1.04-.04*a));feature.style.setProperty('--caption-reveal',String(clamp((a-.15)/.85)));feature.inert=a<.5;feature.classList.toggle('is-active',a>=.5)});featureStack.dataset.activeFeature=String(alphas.indexOf(Math.max(...alphas)))}};if(interlude){const r=interlude.getBoundingClientRect();if(r.bottom>0&&r.top<height){const p=(height-r.top)/(height+r.height);interlude.style.setProperty('--interlude-y',((.5-p)*55).toFixed(1)+'px');interlude.style.setProperty('--interlude-scale',String(.96+p*.07));interlude.style.setProperty('--outline-x',((p-.5)*80).toFixed(1)+'px')}}if(teaser){const r=teaser.getBoundingClientRect();if(r.bottom>0&&r.top<height)teaser.style.setProperty('--teaser-y',((.5-clamp((height-r.top)/(height+r.height)))*45).toFixed(1)+'px')}if(closing){const r=closing.getBoundingClientRect();if(r.bottom>0&&r.top<height){const cp=clamp((height-r.top)/(height*.7));closing.style.setProperty('--closing-clip',(66+cp*55).toFixed(1)+'%');closing.style.setProperty('--closing-y',((.5-clamp((height-r.top)/(height+r.height)))*40).toFixed(1)+'px')}}if(footer){const r=footer.getBoundingClientRect();if(r.top<height)footer.style.setProperty('--footer-clip',(80*(1-clamp((height-r.top)/(r.height*.85)))).toFixed(1)+'%')}}
